7c7dc6a Avoid out-of-bounds read in code fence detection
 src/document.c | 4 +++-
 1 file changed, 3 insertions(+), 1 deletion(-)
commit 7c7dc6ac9adce5413ab54dcd604db95a9b935b05
Author: Martin von Gagern <gagern@google.com>
Date:   Mon Jun 29 13:15:08 2020 +0100

    Avoid out-of-bounds read in code fence detection

diff --git a/src/document.c b/src/document.c
index fcd1696..a504c2e 100644
--- a/src/document.c
+++ b/src/document.c
@@ -1789,8 +1789,10 @@ is_codefence(uint8_t *data, size_t size, size_t *width, uint8_t *chr)
        if (data[2] == ' ') { i++; } } }

        /* looking at the hrule uint8_t */
+       if (i + 2 >= size)
+               return 0;
        c = data[i];
-       if (i + 2 >= size || !(c=='~' || c=='`'))
+       if (!(c=='~' || c=='`'))
                return 0;

        /* the fence must be that same character */
commit d3e7f18309f62ce98853307a93b933078c65c722
Author: Jonas Wagner <jbw@google.com>
Date:   Mon Jun 29 14:41:56 2020 +0100

    Improve loop readability in fence detection

diff --git a/src/document.c b/src/document.c
index e515dcf..ca9fc07 100644
--- a/src/document.c
+++ b/src/document.c
@@ -1806,14 +1806,11 @@ is_codefence(uint8_t *data, size_t size, size_t *width, uint8_t *chr)
        if (n < 3)
                return 0;

-       for (j = i; j < size; ++j) {
+       for (j = i; j < size && data[j] != '\n'; ++j) {
                if (data[j] == c) {
                        /* Avoid parsing codespan as fence. */
                        return 0;
                }
-               if (data[j] == '\n') {
-                       break;
-               }
        }

        if (width) *width = n;
